    workedExample: { title: "La selección cambia la impresión", scenario: "En veinte operaciones ficticias hay doce ganancias. Al mostrar solo las ocho mejores, un informe aparenta una tasa de aciertos perfecta. Una muestra posterior separada tiene ocho ganancias de veinte.", steps: ["Tasa del conjunto original completo = 12/20 × 100 = 60 %.", "Tasa de las ocho elegidas = 8/8 × 100 = 100 %, pero la selección depende del resultado.", "Tasa posterior = 8/20 × 100 = 40 %; la diferencia no identifica por sí sola su causa, pero exige revisar incertidumbre y selección."], conclusion: "Mostrar los mejores casos no estima la frecuencia de éxito. Las dos muestras pequeñas tampoco demuestran por sí solas estabilidad o ausencia de habilidad." },
    commonMistakes: [{ mistake: "Muchos indicadores coincidentes son muchas pruebas independientes.", correction: "Revisar si transforman los mismos datos y si se eligieron después." }, { mistake: "La confianza subjetiva autoriza un riesgo mayor.", correction: "Mantener dimensionamiento basado en reglas y evidencia, no en intensidad emocional." }], summary: ["La evidencia contraria debe recibir el mismo examen.", "Confianza y probabilidad no son equivalentes.", "Seleccionar resultados favorables invalida una estimación representativa."], relatedConcepts: ["Confirmación", "Anclaje", "Disponibilidad", "Calibración"], sources: [behavior, log],
    diagram: { title: "De creencia a prueba", nodes: ["Hipótesis escrita", "Criterio de refutación", "Muestra completa", "Evaluación separada", "Mantener, revisar o descartar"], caption: "Cambiar reglas tras observar la evaluación convierte esos datos en parte del diseño." },
    questions: [
      { type: "number", concept: "Muestra completa", prompt: "Doce ganancias de veinte operaciones: ¿tasa de aciertos?", answer: 60, tolerance: 0, unit: "%", required: true, explanation: "12/20 × 100 = 60 %, incluyendo las ocho pérdidas." },
      { type: "choice", concept: "Confirmación", prompt: "¿Qué práctica limita la búsqueda selectiva de evidencia?", options: ["Definir previamente qué refutaría la idea", "Eliminar los casos que contradicen el relato", "Añadir indicadores hasta acertar"], answer: "Definir previamente qué refutaría la idea", explanation: "Un criterio previo evita adaptar indefinidamente la explicación para que nunca falle." },
      { type: "boolean", concept: "Fuera de muestra", prompt: "Si ajustas una regla tras ver la evaluación, esos datos siguen siendo totalmente independientes del diseño.", answer: "false", explanation: "La información observada ya ha influido en la elección de la regla." },
      { type: "text", concept: "Anclaje", prompt: "Aferrarse al precio de entrada sin una función validada es un posible sesgo de ____.", answer: "anclaje", acceptedAnswers: ["anclaje"], explanation: "Un anclaje concentra la valoración alrededor de una referencia que puede no ser pertinente." },
      { type: "choice", concept: "Confianza", prompt: "¿Qué distingue confianza subjetiva de precisión?", options: ["La precisión se contrasta con resultados y un método", "Toda convicción intensa es estadísticamente correcta", "Ambas son siempre idénticas"], answer: "La precisión se contrasta con resultados y un método", explanation: "La sensación de certeza no reemplaza una comprobación calibrada y suficiente." },
    ],
